-- Feature 20 is an append-only, local-fixture-only Timescale graph.
CREATE TABLE IF NOT EXISTS risk_tiered_consent_scopes (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, proposal_fingerprint text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_registry_snapshots (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, artifact_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_feature19_contexts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, run_id text NOT NULL, context_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,run_id), UNIQUE(operator_test_id,scope_hash,context_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_source_receipts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, source_id text NOT NULL, sequence integer NOT NULL CHECK(sequence>0), artifact_hash char(64) NOT NULL, predecessor_hash char(64), payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,source_id,sequence), UNIQUE(operator_test_id,scope_hash,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_packets (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, packet_hash char(64) NOT NULL, challenge_hash char(64) NOT NULL, expires_at timestamptz NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,packet_hash), UNIQUE(operator_test_id,scope_hash,challenge_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_nonce_consumptions (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, challenge_hash char(64) NOT NULL, receipt_hash char(64) NOT NULL, outcome text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,challenge_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_lifecycle_transitions (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, sequence integer NOT NULL CHECK(sequence>0), artifact_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,sequence), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_request_claims (operator_test_id text NOT NULL, idempotency_key text NOT NULL, request_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_artifacts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, artifact_kind text NOT NULL, artifact_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,artifact_kind,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES risk_tiered_consent_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS risk_tiered_consent_conflicts (operator_test_id text NOT NULL, idempotency_key text NOT NULL, request_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE INDEX IF NOT EXISTS risk_tiered_consent_packets_expiry_idx ON risk_tiered_consent_packets(operator_test_id,expires_at);
CREATE OR REPLACE FUNCTION risk_tiered_consent_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'risk_tiered_consent_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['risk_tiered_consent_scopes','risk_tiered_consent_registry_snapshots','risk_tiered_consent_feature19_contexts','risk_tiered_consent_source_receipts','risk_tiered_consent_packets','risk_tiered_consent_nonce_consumptions','risk_tiered_consent_lifecycle_transitions','risk_tiered_consent_request_claims','risk_tiered_consent_conflicts','risk_tiered_consent_artifacts'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I','risk_tiered_consent_no_mutation',t); EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION risk_tiered_consent_append_only()','risk_tiered_consent_no_mutation',t); END LOOP; END $$;
CREATE OR REPLACE VIEW risk_tiered_consent_current_fixture_projection AS SELECT s.operator_test_id,s.scope_hash,s.proposal_fingerprint,max(t.sequence) AS lifecycle_sequence FROM risk_tiered_consent_scopes s LEFT JOIN risk_tiered_consent_lifecycle_transitions t USING(operator_test_id,scope_hash) GROUP BY s.operator_test_id,s.scope_hash,s.proposal_fingerprint;
